// Drawn placeholders for every road art slot. They show the intended layout,
// mood and state of each picture so the game is complete before the real art
// arrives (see docs/art/ROADMAP.md). Plain SVG, no fonts or images.
import { companionDrawing } from './caravan-art.js';

const ink = '#233e35';
const line = `stroke="${ink}" stroke-width="2.3" stroke-linejoin="round" stroke-linecap="round"`;
const thin = `stroke="${ink}" stroke-width="1.6" stroke-linejoin="round" stroke-linecap="round"`;
let uid = 0;

// Faces ---------------------------------------------------------------------
function eyes(x1, x2, y, pose, r = 3.2) {
  if (pose === 'happy') return `<path d="M${x1 - 4} ${y + 1}q4-5 8 0M${x2 - 4} ${y + 1}q4-5 8 0" fill="none" ${line}/>`;
  if (pose === 'oops') return `<circle cx="${x1}" cy="${y}" r="${r + 1.6}" fill="#fff" ${thin}/><circle cx="${x2}" cy="${y}" r="${r + 1.6}" fill="#fff" ${thin}/><circle cx="${x1 + .5}" cy="${y + .5}" r="${r - .8}" fill="${ink}"/><circle cx="${x2 + .5}" cy="${y + .5}" r="${r - .8}" fill="${ink}"/>`;
  return `<circle cx="${x1}" cy="${y}" r="${r}" fill="${ink}"/><circle cx="${x2}" cy="${y}" r="${r}" fill="${ink}"/>`;
}
function mouth(x, y, pose, w = 10) {
  if (pose === 'talk') return `<ellipse cx="${x}" cy="${y + 2}" rx="${w / 3}" ry="${w / 4}" fill="#7a2f2f" ${thin}/>`;
  if (pose === 'happy') return `<path d="M${x - w / 2} ${y}q${w / 2} ${w * .7} ${w} 0z" fill="#7a2f2f" ${thin}/>`;
  if (pose === 'oops') return `<path d="M${x - w / 3} ${y + 3}q${w / 6}-4 ${w / 3} 0t${w / 3} 0" fill="none" ${thin}/>`;
  return `<path d="M${x - w / 2} ${y}q${w / 2} ${w * .4} ${w} 0" fill="none" ${line}/>`;
}

// Keepers: 120×120 portraits with a round backdrop in the keeper's color.
const drawings = {
  snooze: pose => `<path d="M14 84q2-48 42-50 38 2 42 50z" fill="#6aa86a" ${line}/><path d="M28 80q4-30 28-32 24 2 28 32M42 48l-4 32m36-32 4 32M24 66h66" fill="none" stroke="#3f7a4a" stroke-width="2"/><path d="M10 86h92q-4 10-46 10T10 86z" fill="#d9c27a" ${line}/><ellipse cx="22" cy="98" rx="9" ry="6" fill="#9cc77f" ${line}/><ellipse cx="90" cy="98" rx="9" ry="6" fill="#9cc77f" ${line}/><circle cx="98" cy="64" r="17" fill="#9cc77f" ${line}/>${pose === 'idle' ? `<path d="M88 61q4 3 8 0m4 0q4 3 8 0" fill="none" ${line}/><text x="96" y="38" font-size="12" fill="${ink}" font-family="Georgia,serif">z</text><text x="104" y="28" font-size="9" fill="${ink}" font-family="Georgia,serif">z</text>` : eyes(92, 104, 60, pose, 2.6)}${mouth(98, 70, pose, 8)}<path d="M36 34v-8h40v8" fill="#c9915a" ${thin}/><circle cx="56" cy="22" r="5" fill="#f7cf63" ${thin}/>`,
  hops: pose => `<ellipse cx="60" cy="80" rx="34" ry="26" fill="#62b26e" ${line}/><circle cx="44" cy="50" r="12" fill="#62b26e" ${line}/><circle cx="76" cy="50" r="12" fill="#62b26e" ${line}/><circle cx="44" cy="50" r="7" fill="#fff" ${thin}/><circle cx="76" cy="50" r="7" fill="#fff" ${thin}/>${pose === 'happy' ? `<path d="M40 51q4-5 8 0M72 51q4-5 8 0" fill="none" ${line}/>` : `<circle cx="${pose === 'oops' ? 44 : 45}" cy="51" r="${pose === 'oops' ? 2 : 3.4}" fill="${ink}"/><circle cx="${pose === 'oops' ? 76 : 77}" cy="51" r="${pose === 'oops' ? 2 : 3.4}" fill="${ink}"/>`}<path d="M38 40h44l-6-30H44z" fill="#2f3542" ${line}/><path d="M30 41h60" ${line}/><path d="M42 30h36" stroke="#d4a64a" stroke-width="4"/>${mouth(60, 76, pose, 18)}<path d="M98 104V30" stroke="#8a6a3e" stroke-width="4" stroke-linecap="round"/><path d="M98 30q-6-8 0-16 6 8 0 16z" fill="#ffd25a" ${thin}/><ellipse cx="88" cy="88" rx="8" ry="5" fill="#62b26e" ${thin}/>`,
  billie: pose => `<path d="M38 46q-18-22-4-34m48 34q18-22 4-34" fill="none" stroke="#8b6b4a" stroke-width="6" stroke-linecap="round"/><ellipse cx="60" cy="62" rx="26" ry="30" fill="#f4ecd8" ${line}/><path d="M30 52l-14-6 4 12zm60 0 14-6-4 12z" fill="#efe2c6" ${line}/>${eyes(50, 70, 56, pose, 3)}<ellipse cx="60" cy="76" rx="12" ry="9" fill="#e7cfb5" ${thin}/>${mouth(60, 78, pose, 10)}<path d="M54 90q6 16 12 0" fill="#d8d0bd" ${thin}/><path d="M30 96q30 12 60 0l4 10q-34 14-68 0z" fill="#e35d4a" ${line}/><path d="M86 100q16 2 26-6-4 12-22 14z" fill="#e35d4a" ${line}/>`,
  rattle: pose => `<path d="M28 116q4-34 32-34t32 34" fill="#e9e4d6" ${line}/><path d="M44 92v20m8-22v24m8-24v24m8-22v20" stroke="#bdb5a0" stroke-width="2"/><circle cx="60" cy="54" r="26" fill="#f2eee2" ${line}/><path d="M48 74v8h24v-8" fill="#f2eee2" ${line}/><path d="M53 74v8m7-8v8m7-8v8" stroke="${ink}" stroke-width="1.4"/>${pose === 'happy' ? `<path d="M42 54q6-8 12 0M66 54q6-8 12 0" fill="none" stroke="${ink}" stroke-width="3" stroke-linecap="round"/>` : `<ellipse cx="49" cy="52" rx="${pose === 'oops' ? 8 : 7}" ry="${pose === 'oops' ? 9 : 7}" fill="#2a2140"/><ellipse cx="71" cy="52" rx="${pose === 'oops' ? 8 : 7}" ry="${pose === 'oops' ? 9 : 7}" fill="#2a2140"/><circle cx="50" cy="53" r="2" fill="#ffb347"/><circle cx="72" cy="53" r="2" fill="#ffb347"/>`}<path d="M57 63l3-5 3 5z" fill="#2a2140"/>${pose === 'talk' ? '<ellipse cx="60" cy="72" rx="6" ry="3" fill="#2a2140"/>' : ''}<path d="M30 90q30 10 60 0l2 8q-32 12-64 0z" fill="#ff8a1f" ${line}/><path d="M34 30q26-22 52 0l-4-10q-22-12-44 0z" fill="#9a6fd1" ${line}/>`,
  sprocket: pose => `<path d="M88 104q24-8 22-40-10 2-14 22" fill="#7c7f86" ${line}/><path d="M96 70l10 2m-12 8 12 3m-14 8 10 4" stroke="#2f3238" stroke-width="4"/><circle cx="36" cy="34" r="10" fill="#7c7f86" ${line}/><circle cx="84" cy="34" r="10" fill="#7c7f86" ${line}/><ellipse cx="60" cy="62" rx="32" ry="28" fill="#9a9da5" ${line}/><path d="M30 58q30-14 60 0v10q-30 10-60 0z" fill="#33363c"/>${eyes(48, 72, 62, pose, 3)}<ellipse cx="60" cy="76" rx="10" ry="7" fill="#eceae4" ${thin}/><circle cx="60" cy="72" r="3" fill="${ink}"/>${mouth(60, 79, pose, 9)}<circle cx="46" cy="40" r="8" fill="#a8d6e8" ${line}/><circle cx="74" cy="40" r="8" fill="#a8d6e8" ${line}/><path d="M54 40h12" ${line}/><path d="M34 100h52v12H34z" fill="#8a5a33" ${line}/><circle cx="46" cy="106" r="3" fill="#e2b04a"/><circle cx="74" cy="106" r="3" fill="#e2b04a"/>`,
  wick: pose => `<ellipse cx="60" cy="72" rx="32" ry="36" fill="#8b6a4a" ${line}/><path d="M34 38l6 14m46-14-6 14" ${line}/><path d="M28 54q32-34 64 0v-14q-32-30-64 0z" fill="#f2c94c" ${line}/><circle cx="47" cy="66" r="12" fill="#fff6d8" ${line}/><circle cx="73" cy="66" r="12" fill="#fff6d8" ${line}/>${pose === 'happy' ? `<path d="M42 67q5-6 10 0M68 67q5-6 10 0" fill="none" ${line}/>` : `<circle cx="47" cy="${pose === 'idle' ? 68 : 66}" r="${pose === 'oops' ? 6 : 4.5}" fill="${ink}"/><circle cx="73" cy="${pose === 'idle' ? 68 : 66}" r="${pose === 'oops' ? 6 : 4.5}" fill="${ink}"/>`}${pose === 'idle' ? `<path d="M36 62h22m4 0h22" stroke="#8b6a4a" stroke-width="5"/>` : ''}<path d="M56 78l4 8 4-8z" fill="#e8a33c" ${thin}/><path d="M34 96q26 16 52 0v14H34z" fill="#f2c94c" ${line}/>${pose === 'talk' ? '<path d="M57 86h6" stroke="#7a2f2f" stroke-width="2"/>' : ''}`,
  plume: pose => `${[-60, -35, -12, 12, 35, 60].map((a, i) => `<g transform="rotate(${a} 60 96)"><path d="M60 96L60 20" stroke="#2f8f6f" stroke-width="10" stroke-linecap="round"/><circle cx="60" cy="22" r="9" fill="#1f6f8f" ${thin}/><circle cx="60" cy="22" r="4.5" fill="#f2c94c"/><circle cx="60" cy="22" r="2" fill="#2a2140"/></g>`).join('')}<ellipse cx="60" cy="90" rx="18" ry="22" fill="#2f8fa8" ${line}/><circle cx="60" cy="58" r="15" fill="#2f8fa8" ${line}/><path d="M54 44l-4-12m10 10V28m6 14 4-12" ${thin}/><circle cx="50" cy="31" r="3" fill="#f2c94c"/><circle cx="60" cy="27" r="3" fill="#f2c94c"/><circle cx="70" cy="31" r="3" fill="#f2c94c"/>${pose === 'oops' ? eyes(54, 66, 56, 'oops', 2.2) : pose === 'happy' ? eyes(54, 66, 56, 'happy') : `<path d="M50 54h8m4 0h8" ${line}/><circle cx="55" cy="57" r="2.2" fill="${ink}"/><circle cx="67" cy="57" r="2.2" fill="${ink}"/>`}<path d="M56 63l4 7 4-7z" fill="#f29a3a" ${thin}/>${pose === 'talk' ? '<path d="M57 66h6" stroke="#7a2f2f" stroke-width="2"/>' : ''}`,
};

export function keeperArt(id, pose = 'idle', color = '#cfd8c4') {
  const draw = drawings[id] || drawings.hops;
  return `<svg class="ph-keeper" viewBox="0 0 120 120" aria-hidden="true" xmlns="http://www.w3.org/2000/svg"><circle cx="60" cy="60" r="58" fill="${color}" opacity=".28"/><g class="ph-pose-${pose}">${draw(pose)}</g></svg>`;
}

// Scenes --------------------------------------------------------------------
const MOODS = {
  ferry: { sky: ['#9fdcff', '#fff0c2'], ground: '#f2d27e', far: '#58c0cf', accent: '#ff9e5e' },
  marsh: { sky: ['#14213f', '#2c4a63'], ground: '#1e4b45', far: '#24585a', accent: '#c6ff6b' },
  ridge: { sky: ['#7fd0ff', '#e6f7ff'], ground: '#7ab46b', far: '#5b8f68', accent: '#ff5f7a' },
  hollow: { sky: ['#24123a', '#5e2a72'], ground: '#2c2238', far: '#3c2b52', accent: '#ff8a1f' },
  workshop: { sky: ['#5b3a2a', '#8a5a3a'], ground: '#a8743f', far: '#6e4a33', accent: '#ffcf6a' },
  lighthouse: { sky: ['#17233a', '#3a4f78'], ground: '#1f3b63', far: '#2c4c78', accent: '#fff09a' },
  fair: { sky: ['#2a1758', '#7a2f86'], ground: '#3a2a62', far: '#4e2f78', accent: '#ffd23f' },
};
export const moodOf = stop => MOODS[stop] || MOODS.ferry;

const lamp = (x, y, lit, s = 1, glow = '#ffe27a') => `<g transform="translate(${x} ${y}) scale(${s})">${lit ? `<circle r="22" cy="-16" fill="${glow}" opacity=".28"/><circle r="12" cy="-16" fill="${glow}" opacity=".45"/>` : ''}<path d="M0 18v-24" ${line}/><path d="M-8-6h16l-3-18h-10z" fill="${lit ? glow : '#59606b'}" ${line}/></g>`;
const star = (x, y, r = 3) => `<circle cx="${x}" cy="${y}" r="${r}" fill="#fff8d0" opacity=".85"/>`;
const party = (n = 6, y = 182, x0 = 300, s = .34, gap = 44) => ['pip', 'moss', 'rook', 'bea', 'fern', 'tumble'].slice(0, n).map((id, i) => `<g transform="translate(${x0 + i * gap} ${y + (i % 2) * 6}) scale(${s})">${companionDrawing(id)}</g>`).join('');

const sceneParts = {
  ferry: stage => `<path d="M0 132q150-18 300 0t300 0v88H0z" fill="#3bb5c8"/><path d="M0 150q150-14 300 0t300 0" stroke="#bff0f5" stroke-width="3" fill="none" opacity=".7"/><path d="M0 178q80-10 170 4v38H0z" fill="#f2d27e"/><path d="M20 120h120v10H20z" fill="#b98a55" ${line}/><path d="M36 130v40m40-40v40m40-40v40" stroke="#8a6238" stroke-width="5"/>
    <g transform="translate(${stage >= 2 ? 420 : 330} 128)"><path d="M-80 0q4-50 80-54 76 4 80 54z" fill="#6aa86a" ${line}/><path d="M-60-4q6-32 60-36 54 4 60 36" fill="none" stroke="#3f7a4a" stroke-width="2"/><circle cx="96" cy="-6" r="20" fill="#9cc77f" ${line}/>${stage >= 2 ? `<circle cx="100" cy="-10" r="3" fill="${ink}"/><path d="M-110 6q-20-6-34 4m24 8q-20-4-30 6" stroke="#fff" stroke-width="3" fill="none" opacity=".8"/>` : `<path d="M94-10q4 3 8 0" fill="none" ${line}/>`}${stage >= 1 ? party(Math.min(6, 6), -66, -64, .26, 22) : '<path d="M-50-38h28v-10h-28zm40 0h28v-10H-10z" fill="#c9915a" ' + thin + '/>'}${lamp(-70, -40, stage >= 3, .7)}${lamp(70, -40, stage >= 3, .7)}</g>${lamp(30, 112, stage >= 3)}${lamp(126, 112, stage >= 3)}`,
  marsh: stage => `${Array.from({ length: 26 }, (_, i) => `<circle cx="${(i * 97) % 600}" cy="${30 + (i * 53) % 110}" r="${1.5 + (i % 3)}" fill="#c6ff6b" opacity="${.35 + (i % 4) * .15}"/>`).join('')}<path d="M0 150q300-26 600 0v70H0z" fill="#1c3f3d"/>${[40, 90, 470, 520, 570].map(x => `<path d="M${x} 160q-6-40 2-70m0 70q10-30 4-58" stroke="#3d7a52" stroke-width="4" fill="none"/>`).join('')}<path d="M90 168h420" stroke="#9a7a4a" stroke-width="10"/><path d="M110 168v22m100-22v22m100-22v22m100-22v22m80-22v22" stroke="#6e5530" stroke-width="5"/>${[150, 300, 450].map((x, i) => lamp(x, 152, stage >= 1 && i < 3, .9, '#c6ff6b')).join('')}${[[200, 196], [330, 204], [430, 194]].map(([x, y]) => `<ellipse cx="${x}" cy="${y}" rx="24" ry="8" fill="#3fa36a" ${thin}/>${stage >= 2 ? `<circle cx="${x}" cy="${y - 4}" r="5" fill="#ff7ab8" ${thin}/>` : ''}`).join('')}${stage >= 3 ? '<ellipse cx="300" cy="188" rx="240" ry="12" fill="#c6ff6b" opacity=".18"/>' : ''}`,
  ridge: stage => `<path d="M0 150 90 60l70 60 90-100 100 110 80-70 170 90v110H0z" fill="#5b8f68" ${line}/><path d="M230 40l20-20 24 30-22-6zm170 60 14-12 18 18z" fill="#fff"/><path d="M0 170q300-40 600 0v50H0z" fill="#7ab46b"/><path d="M40 40 560 90" stroke="${ink}" stroke-width="2"/><g transform="translate(${stage >= 1 ? 470 : 120} ${stage >= 1 ? 86 : 52})"><path d="M0 0v14m-22 0h44v26h-44z" fill="#e35d4a" ${line}/><path d="M-16 20h32v10h-32z" fill="#cdeeff"/></g>${stage < 2 ? '<g transform="translate(470 172)"><path d="M-40 0h80v-34h-80z" fill="#2f8fa8" ' + line + '/><path d="M-40-34q40-40 80 0" fill="#2f8f6f" ' + line + '/><circle cx="-24" cy="4" r="9" fill="#5a4a3a"/><circle cx="24" cy="4" r="9" fill="#5a4a3a"/></g>' : ''}${stage >= 3 ? [[150, 40, '#ff5f7a'], [230, 26, '#ffd23f'], [330, 44, '#4fb3ff'], [400, 22, '#8a5cff']].map(([x, y, c]) => `<path d="M${x} ${y}l14 16-14 16-14-16z" fill="${c}" ${thin}/><path d="M${x} ${y + 32}q-10 30 10 60" stroke="${ink}" fill="none" stroke-width="1.2"/>`).join('') : ''}`,
  hollow: stage => `<circle cx="480" cy="54" r="30" fill="#ffe9a8"/><circle cx="492" cy="48" r="26" fill="#3f2156" opacity=".25"/>${[60, 160, 250, 370, 540].map((x, i) => star(x, 22 + (i * 17) % 40, 1.6)).join('')}<path d="M0 160q300-30 600 0v60H0z" fill="#2c2238"/><path d="M60 170V70m0 20 30-30m-30 50-24-26" stroke="#1a1424" stroke-width="7" fill="none" stroke-linecap="round"/>${[[180, 168], [240, 172], [520, 170]].map(([x, y]) => `<path d="M${x - 14} ${y}v-26q14-16 28 0v26z" fill="#8a8aa8" ${line}/>`).join('')}<g transform="translate(380 172)"><path d="M-40 0v-46q40-30 80 0V0z" fill="#5a5070" ${line}/><path d="M-20 0v-30q20-14 40 0V0z" fill="${stage >= 2 ? '#ffcf6a' : '#251d33'}" ${line}/></g>${[[110, 196], [290, 200], [470, 198], [560, 194]].map(([x, y]) => `<g transform="translate(${x} ${y})"><ellipse rx="16" ry="12" fill="#ff8a1f" ${line}/><path d="M0-12v-6" stroke="#3d7a52" stroke-width="3"/>${stage >= 1 ? '<path d="M-7-3l3-3 3 3zm8 0 3-3 3 3zM-6 4q6 4 12 0" fill="#ffe27a" stroke="#ffe27a" stroke-width="1.5"/><circle r="22" fill="#ffb347" opacity=".2"/>' : ''}</g>`).join('')}${stage >= 3 ? '<path d="M150 210h120m-120 0v-14h120v14M190 196v14m40-14v14" stroke="#fff" stroke-width="2.4" fill="none" opacity=".85"/>' : ''}`,
  workshop: stage => `<path d="M0 0h600v170H0z" fill="#7a4e33"/><path d="M60 30h120v90H60z" fill="#3e5f80" ${line}/>${Array.from({ length: 12 }, (_, i) => `<path d="M${70 + (i * 23) % 100} ${36 + (i * 31) % 70}l-4 10" stroke="#a8c8e8" stroke-width="2"/>`).join('')}<path d="M120 30v90M60 75h120" ${line}/><circle cx="420" cy="62" r="34" fill="#c9a04a" ${line}/><circle cx="420" cy="62" r="10" fill="#7a4e33" ${line}/>${Array.from({ length: 8 }, (_, i) => `<path d="M420 28v-8" transform="rotate(${i * 45} 420 62)" stroke="${ink}" stroke-width="6"/>`).join('')}${lamp(300, 40, stage >= 3, 1, '#ffcf6a')}<path d="M0 170h600v50H0z" fill="#a8743f"/>${stage >= 1 ? '' : '<ellipse cx="250" cy="196" rx="44" ry="12" fill="#2a1a10"/>'}<path d="M330 150h140v20H330z" fill="#8a5a33" ${line}/>${stage >= 2 ? '<g transform="translate(380 130)"><path d="M-14 20v-30h28v30z" fill="#4fb3ff" ' + line + '/><path d="M14-4h16v-10" fill="none" ' + line + '/><circle cy="-14" r="6" fill="#e2b04a" ' + thin + '/></g>' : ''}${stage >= 3 ? '<path d="M500 120h60v50h-60z" fill="#c4703f" ' + line + '/><circle cx="515" cy="135" r="6" fill="#e2b04a"/><circle cx="545" cy="135" r="6" fill="#e2b04a"/><circle cx="530" cy="155" r="6" fill="#e2b04a"/>' : ''}`,
  lighthouse: stage => `${[40, 130, 220, 520].map((x, i) => star(x, 20 + i * 9, 1.4)).join('')}<path d="M0 30q120 20 240 0t360 10" stroke="#2c3a58" stroke-width="18" fill="none" opacity=".6"/>${stage >= 1 ? `<path d="M430 48 ${stage >= 2 ? '120 0' : '60 80'}v60L430 64z" fill="#fff09a" opacity=".35"/>` : ''}<path d="M0 160q100-24 200 0t200 0 200 0v60H0z" fill="#1f3b63"/><path d="M0 176q100-16 200 0t200 0 200 0" stroke="#9ec3ff" stroke-width="3" fill="none" opacity=".6"/><path d="M400 168l14-120h32l14 120z" fill="#f4efe6" ${line}/><path d="M406 128h48l3 22h-54zm6-50h36l2 22h-40z" fill="#e35d4a"/><path d="M410 48h40v-14h-40z" fill="${stage >= 1 ? '#fff09a' : '#3a4f78'}" ${line}/><path d="M404 34h52l-26-18z" fill="#e35d4a" ${line}/>${[60, 130, 200].map(x => lamp(x, 156, stage >= 3, .8, '#fff09a')).join('')}`,
  fair: stage => `${Array.from({ length: 14 }, (_, i) => star((i * 83) % 600, 14 + (i * 29) % 60, 1.3)).join('')}<path d="M0 166h600v54H0z" fill="#3a2a62"/><circle cx="470" cy="96" r="58" fill="none" ${line}/>${Array.from({ length: 8 }, (_, i) => `<path d="M470 96 ${470 + 58 * Math.cos(i * Math.PI / 4)} ${96 + 58 * Math.sin(i * Math.PI / 4)}" ${thin}/><circle cx="${470 + 58 * Math.cos(i * Math.PI / 4)}" cy="${96 + 58 * Math.sin(i * Math.PI / 4)}" r="7" fill="${['#ff5f7a', '#ffd23f', '#4fb3ff', '#8a5cff'][i % 4]}" ${thin}/>`).join('')}<path d="M440 168l30-72 30 72" fill="none" ${line}/>${[[90, '#ff5f7a'], [220, '#ffd23f']].map(([x, c]) => `<path d="M${x - 50} 168v-50h100v50z" fill="#fff6e0" ${line}/><path d="M${x - 56} 120l56-40 56 40z" fill="${c}" ${line}/><path d="M${x - 50} 130h100" stroke="${c}" stroke-width="8"/>`).join('')}<path d="M0 60q150 40 300 0t300 0" stroke="${ink}" stroke-width="1.4" fill="none"/>${Array.from({ length: 12 }, (_, i) => `<circle cx="${25 + i * 50}" cy="${62 + 18 * Math.sin(i / 1.9)}" r="5" fill="${stage >= 1 ? ['#ff5f7a', '#ffd23f', '#4fb3ff'][i % 3] : '#4e3f72'}"/>`).join('')}${stage >= 3 ? [[140, 40, '#ffd23f'], [320, 30, '#ff5f7a'], [380, 60, '#4fb3ff']].map(([x, y, c]) => Array.from({ length: 10 }, (_, i) => `<path d="M${x} ${y}l${18 * Math.cos(i * Math.PI / 5)} ${18 * Math.sin(i * Math.PI / 5)}" stroke="${c}" stroke-width="3" stroke-linecap="round"/>`).join('')).join('') : ''}`,
};

// Party members stand in the foreground of every scene, busy with the stop.
export function sceneArt(stop, stage = 0) {
  const mood = moodOf(stop), id = `ph-sky-${++uid}`;
  const crew = stop === 'ferry' && stage >= 1 ? '' : party(6, 184, 196, .3, 40);
  return `<svg class="ph-scene" viewBox="0 0 600 220" preserveAspectRatio="xMidYMid slice" aria-hidden="true" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="${id}" x2="0" y2="1"><stop stop-color="${mood.sky[0]}"/><stop offset="1" stop-color="${mood.sky[1]}"/></linearGradient></defs><rect width="600" height="220" fill="url(#${id})"/>${(sceneParts[stop] || sceneParts.ferry)(stage)}${crew}</svg>`;
}

// Map -----------------------------------------------------------------------
// Stop positions are shared with the overlay buttons in road-ui.js, in percent.
export const MAP_POINTS = {
  wide: { ferry: [9, 70], marsh: [24, 38], ridge: [39, 66], hollow: [53, 30], workshop: [66, 70], lighthouse: [80, 34], fair: [92, 64] },
  tall: { ferry: [28, 84], marsh: [70, 72], ridge: [30, 59], hollow: [70, 46], workshop: [28, 33], lighthouse: [72, 20], fair: [34, 7] },
};
const mapIcons = {
  ferry: '<path d="M-26 6q2-24 26-26 24 2 26 26z" fill="#6aa86a" ' + line + '/><circle cx="30" cy="0" r="9" fill="#9cc77f" ' + line + '/><path d="M-40 12q40 10 80 0" stroke="#3bb5c8" stroke-width="6" fill="none"/>',
  marsh: '<ellipse cy="8" rx="34" ry="10" fill="#1e4b45"/><path d="M-20 8q-4-26 2-36m14 36q6-20 2-34m16 34q-2-22 6-30" stroke="#3d7a52" stroke-width="4" fill="none"/><circle cx="-8" cy="-22" r="3" fill="#c6ff6b"/><circle cx="14" cy="-30" r="3" fill="#c6ff6b"/>',
  ridge: '<path d="M-36 10 0-30 36 10z" fill="#5b8f68" ' + line + '/><path d="M-8-20 0-30 8-20z" fill="#fff"/>',
  hollow: '<path d="M-30 10v-22q30-26 60 0v22" fill="#5a5070" ' + line + '/><circle cx="-26" cy="-26" r="9" fill="#ffe9a8"/><ellipse cx="18" cy="6" rx="10" ry="7" fill="#ff8a1f" ' + thin + '/>',
  workshop: '<path d="M-28 10v-26h56v26z" fill="#c4935e" ' + line + '/><path d="M-34-16 0-38l34 22z" fill="#7a4e33" ' + line + '/><circle cx="0" cy="-2" r="7" fill="#e2b04a" ' + thin + '/>',
  lighthouse: '<path d="M-10 12l4-44h12l4 44z" fill="#f4efe6" ' + line + '/><path d="M-8-6h16M-7-20h14" stroke="#e35d4a" stroke-width="5"/><path d="M-8-32h16v-8H-8z" fill="#fff09a" ' + thin + '/>',
  fair: '<path d="M-34 12v-18h28v18zm34 0v-18h28v18z" fill="#fff6e0" ' + line + '/><path d="M-38-6l18-18 18 18zm34 0 18-18 18 18z" fill="#ff5f7a" ' + line + '/><circle cx="0" cy="-34" r="4" fill="#ffd23f"/>',
};
export function mapArt(layout = 'wide', lit = []) {
  const wide = layout === 'wide', w = wide ? 1000 : 600, h = wide ? 420 : 900, pts = MAP_POINTS[layout], ids = Object.keys(pts);
  const xy = id => [pts[id][0] * w / 100, pts[id][1] * h / 100];
  const path = ids.map((id, i) => { const [x, y] = xy(id); if (!i) return `M${x} ${y}`; const [px, py] = xy(ids[i - 1]); return wide ? `C${(px + x) / 2} ${py} ${(px + x) / 2} ${y} ${x} ${y}` : `C${px} ${(py + y) / 2} ${x} ${(py + y) / 2} ${x} ${y}`; }).join(' ');
  const g = `ph-map-${++uid}`;
  // Each stop sits on a patch of its own mood, bright and dark alternating.
  const patches = ids.map(id => { const [x, y] = xy(id), m = moodOf(id); return `<ellipse cx="${x}" cy="${y}" rx="${wide ? 82 : 120}" ry="${wide ? 70 : 64}" fill="${m.sky[0]}" opacity=".9"/><ellipse cx="${x}" cy="${y + 16}" rx="${wide ? 70 : 100}" ry="${wide ? 30 : 26}" fill="${m.ground}"/>`; }).join('');
  const icons = ids.map(id => { const [x, y] = xy(id); return `<g transform="translate(${x} ${y + 4}) scale(${wide ? 1 : 1.15})" class="${lit.includes(id) ? 'ph-lit' : ''}">${lit.includes(id) ? `<circle cy="-8" r="40" fill="#ffe27a" opacity=".35"/>` : ''}${mapIcons[id]}</g>`; }).join('');
  return `<svg class="ph-map" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" aria-hidden="true" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="${g}" x2="${wide ? 1 : 0}" y2="${wide ? 0 : 1}"><stop stop-color="#cfeec0"/><stop offset=".45" stop-color="#b9d8a8"/><stop offset="1" stop-color="#4a3a72"/></linearGradient></defs><rect width="${w}" height="${h}" fill="url(#${g})"/>${patches}<path d="${path}" fill="none" stroke="#6b5a3e" stroke-width="${wide ? 14 : 16}" stroke-linecap="round" opacity=".55"/><path d="${path}" fill="none" stroke="#fff4d0" stroke-width="4" stroke-dasharray="2 12" stroke-linecap="round"/>${icons}</svg>`;
}

export function wagonArt(who = 'party') {
  if (who === 'plume') return `<svg class="ph-wagon" viewBox="0 0 120 90" aria-hidden="true" xmlns="http://www.w3.org/2000/svg"><path d="M14 64h84V34H14z" fill="#2f8fa8" ${line}/><path d="M14 34q42-50 84 0" fill="#2f8f6f" ${line}/>${[30, 56, 82].map(x => `<circle cx="${x}" cy="22" r="6" fill="#1f6f8f" ${thin}/><circle cx="${x}" cy="22" r="2.6" fill="#f2c94c"/>`).join('')}<circle cx="32" cy="70" r="11" fill="#5a4a3a" ${line}/><circle cx="82" cy="70" r="11" fill="#5a4a3a" ${line}/></svg>`;
  return `<svg class="ph-wagon" viewBox="0 0 120 90" aria-hidden="true" xmlns="http://www.w3.org/2000/svg"><path d="M14 64h84V36H14z" fill="#c9915a" ${line}/><path d="M14 36q42-36 84 0" fill="#f4ecd8" ${line}/><path d="M56 34V12" stroke="#705d42" stroke-width="4"/><circle cx="56" cy="14" r="14" fill="#8ca36b" ${line}/><circle cx="48" cy="12" r="3" fill="#ffe27a"/><circle cx="62" cy="8" r="3" fill="#ffe27a"/><circle cx="32" cy="70" r="11" fill="#5a4a3a" ${line}/><circle cx="82" cy="70" r="11" fill="#5a4a3a" ${line}/></svg>`;
}

export function toolArt(id) {
  if (id === 'pump') return `<svg class="ph-tool" viewBox="0 0 48 48" aria-hidden="true"><path d="M14 40V18h18v22z" fill="#4fb3ff" ${line}/><path d="M32 22h8v-8" fill="none" ${line}/><circle cx="23" cy="12" r="6" fill="#e2b04a" ${line}/></svg>`;
  return `<svg class="ph-tool" viewBox="0 0 48 48" aria-hidden="true"><path d="M10 34 32 12l6 6-22 22z" fill="#f4efe6" ${line}/><path d="M10 34l6 6-8 2z" fill="#cfc8b8" ${line}/></svg>`;
}

export function finaleArt() {
  return `<svg class="ph-scene ph-finale" viewBox="0 0 600 260" preserveAspectRatio="xMidYMid slice" aria-hidden="true" xmlns="http://www.w3.org/2000/svg"><rect width="600" height="260" fill="#2a1758"/>${sceneParts.fair(3).replace(/translate\(/g, 'translate(')}${party(6, 214, 150, .36, 52)}${['snooze', 'hops', 'billie', 'rattle', 'sprocket', 'wick'].map((id, i) => `<g transform="translate(${30 + i * 92} 150) scale(.42)">${drawings[id]('happy')}</g>`).join('')}</svg>`;
}
